import pandas as pd, numpy as np
exec(open('/tmp/harness.py').read())

fit = pd.read_pickle('/tmp/fit.pkl')
score = pd.read_pickle('/tmp/score.pkl')
g = pd.read_csv('data/groundings.csv.gz', parse_dates=['occurred_at'])
fit_end = fit.departed_at.max()
seen = g[g.occurred_at <= fit_end].sort_values('occurred_at')
base = float(len(seen))/len(fit)
fs = fit_end - pd.Timedelta(days=14)
lately = fit[fit.departed_at >= fs]
fort_fl = lately.groupby('tail_number').size().astype(float)
ev_fort = seen[seen.occurred_at >= fs].groupby('tail_number').size().astype(float)

legs = fit[['tail_number','departed_at','departure_delay']].sort_values('departed_at', kind='stable')
dep_by = {t: gr.departed_at.to_numpy() for t,gr in legs.groupby('tail_number', sort=False)}
dd_by = {t: gr.departure_delay.to_numpy(float) for t,gr in legs.groupby('tail_number', sort=False)}
ev_by = {t: gr.occurred_at.to_numpy() for t,gr in seen.groupby('tail_number', sort=False)}
pf_gap = float((fit_end - fit.groupby('tail_number').departed_at.max()).dt.total_seconds().mean()/86400)
pf_dd = float(fit.departure_delay.mean())

def col_rr(d, mode):
    t = d.tail_number
    if mode=='mine':
        rr = ev_fort.reindex(fort_fl.index).fillna(0)/fort_fl
        return t.map(rr).fillna(base)
    if mode=='nan0':
        rr = ev_fort.reindex(fort_fl.index).fillna(0)/fort_fl
        return t.map(rr).fillna(0.0)
    if mode=='perday':
        rr = ev_fort/14.0
        return t.map(rr).fillna(0.0)
    if mode=='labfort':
        rr = lately.groupby('tail_number')['label'].mean()
        return t.map(rr).fillna(base)

def col_gap(d, mode):
    if mode=='static':
        gp = (fit_end - fit.groupby('tail_number').departed_at.max()).dt.total_seconds()/86400
        return d.tail_number.map(gp).fillna(pf_gap)
    tails=d.tail_number.to_numpy(); when=d.departed_at.to_numpy(); out=np.empty(len(d))
    for i in range(len(d)):
        deps=dep_by.get(tails[i])
        if deps is None: out[i]=pf_gap; continue
        hi=np.searchsorted(deps, when[i],'left')
        out[i]=(when[i]-deps[hi-1])/np.timedelta64(1,'s')/86400.0 if hi>0 else pf_gap
    return pd.Series(out, index=d.index)

def col_rd(d, mode):
    if mode=='static':
        rd = legs.groupby('tail_number').tail(20).groupby('tail_number')['departure_delay'].mean()
        return d.tail_number.map(rd).fillna(pf_dd)
    tails=d.tail_number.to_numpy(); when=d.departed_at.to_numpy(); out=np.empty(len(d))
    for i in range(len(d)):
        deps=dep_by.get(tails[i])
        if deps is None: out[i]=pf_dd; continue
        hi=np.searchsorted(deps, when[i],'left')
        w=dd_by[tails[i]][max(0,hi-20):hi]
        out[i]=np.nanmean(w) if len(w) else pf_dd
    return pd.Series(out, index=d.index)

def col_ds(d, mode):
    if mode=='static':
        last = seen.groupby('tail_number')['occurred_at'].max()
        ds = (fit_end - last).dt.total_seconds()/86400
        return d.tail_number.map(ds).fillna(-1.0)
    tails=d.tail_number.to_numpy(); when=d.departed_at.to_numpy(); out=np.empty(len(d))
    for i in range(len(d)):
        ev=ev_by.get(tails[i])
        if ev is None: out[i]=-1.0; continue
        k=np.searchsorted(ev, when[i],'left')
        out[i]=(when[i]-ev[k-1])/np.timedelta64(1,'s')/86400.0 if k>0 else -1.0
    return pd.Series(out, index=d.index)

def col_tr(d, mode):
    flights = fit.groupby('tail_number').size().astype(float)
    if mode=='mine':
        evn = seen.groupby('tail_number').size().astype(float)
        tr = evn.reindex(flights.index).fillna(0)/flights
        return d.tail_number.map(tr).fillna(base)
    tr = fit.groupby('tail_number')['label'].mean()
    return d.tail_number.map(tr).fillna(base)

import json, time
res=[]
grid = list(itertools.product(['mine','nan0','perday','labfort'],['static','asof'],['static'],['static'],['mine']))
for rr,gap,rd,ds,tr in grid:
    f2,s2 = fit.copy(), score.copy()
    for d in (f2,s2):
        d['f_recent_grounding_rate']=col_rr(d,rr)
        d['f_days_since_prev_flight']=col_gap(d,gap)
        d['f_recent_dep_delay']=col_rd(d,rd)
        d['f_tail_days_since_grounding']=col_ds(d,ds)
        d['f_tail_grounding_rate']=col_tr(d,tr)
        d['f_tail_vs_portfolio']=d['f_tail_grounding_rate']-base
    evaluate(f2,s2,'rr=%s gap=%s rd=%s ds=%s tr=%s'%(rr,gap,rd,ds,tr))
